def svg(name, label=None):
    """One 16px icon in the text colour; `label` makes it announced, otherwise it is decorative."""
    aria = f'role="img" aria-label="{label}"' if label else 'aria-hidden="true"'
    return (f'<svg class="oct" {aria} viewBox="0 0 16 16" width="14" height="14" fill="currentColor">'
            f'<path d="{PATHS[name]}"></path></svg>')
